-- 2903 🏋️ Exercises from the book "j-rgen-klopp-80-attacking-combinations-finishing-positional-patterns-of-play-tra" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'j-rgen-klopp-80-attacking-combinations-finishing-positional-patterns-of-play-tra');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Midfield combos, switch to winger, cross', 'combination', 'unopposed', 'in_possession', 17, 17, 'Attacking Positional Patterns of Play 1', 'Klopp (Liverpool)', 'Rehearse a central midfield combination that switches play to the far winger for a cross and finish.', 'Attacking half of a full pitch, 10 outfield players in Liverpool''s 4-3-3 roles plus a GK in goal; mannequins (or resting centre backs) mark the build-up start near halfway.', 'LCB into DM, DM one-two with RCM then across to LCM, out to LW who drives a firm ground pass back to the DM in the middle; DM to RCM who floats a ball over the top for the LW''s forward run; LW carries and crosses while several players attack the box.', NULL, NULL, 'Timed forward runs into the box from many players; RCM arrives at the edge of the box for the cross.', '10 + GK', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 10),
  ('Double switch, lay-offs, full back overlap', 'combination', 'unopposed', 'in_possession', 18, 18, 'Attacking Positional Patterns of Play 2', 'Klopp (Liverpool)', 'Two switches of play using lay-offs, ending with the full back''s overlap and a cut-back finish.', 'Attacking half of a full pitch, 10 outfield players in Liverpool''s 4-3-3 roles plus a GK in goal; mannequins (or resting centre backs) mark the build-up start near halfway.', 'RCB to RB, inside to DM who moves it to LCM, out to overlapping LB (switch 1); LB to LW who curls wide, touches and returns to LB; LB inside to LCM who hits an aerial switch to RW cutting inside; RW sets RCM who releases RB on a deep overlap; RB finds CF in the box who lays back for RB to finish.', NULL, NULL, 'Lay-offs set up the next forward pass; full back times the overlap.', '10 + GK', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 20),
  ('Triple switch of play into forward to shoot', 'combination', 'unopposed', 'in_possession', 19, 19, 'Attacking Positional Patterns of Play 3', 'Klopp (Liverpool)', 'Three switches of play with rotations, finishing with the forward shooting from the edge of the box.', 'Attacking half of a full pitch, 10 outfield players in Liverpool''s 4-3-3 roles plus a GK in goal; mannequins (or resting centre backs) mark the build-up start near halfway.', 'RCB-RB-DM, DM across to inverted LB who finds LCM; LCM to LW who returns to LB; LB inside to DM on a curved run; DM to RCM releasing advanced RB; RB to RW who plays back inside to DM; DM switches to LW; LW finds LCM''s advanced run, LCM lays off, LW into CF who turns and shoots from the edge of the box.', NULL, NULL, 'Inverted full back and curved DM run to receive.', '10 + GK', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 30),
  ('Lofted switch in behind to far winger', 'combination', 'unopposed', 'in_possession', 20, 20, 'Attacking Positional Patterns of Play 4', 'Klopp (Liverpool)', 'Switch the point of attack with a lofted pass in behind for the opposite winger to finish.', 'Attacking half; 10 outfield players in 4-3-3 roles start from LCB, resting yellow centre backs and a ball supply in the centre circle; GK in goal.', 'LCB to DM, DM forward to CF who drops left and sets LB; LB inside to LCM; LW, CF, RCM and RW run forward and LCM lofts the ball into the box for the far-side RW''s run; RW scores past the GK.', NULL, NULL, 'Several forward runs at once to stretch the line.', '10 + GK', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 40),
  ('Switch + DM joins attack with combos', 'combination', 'unopposed', 'in_possession', 21, 21, 'Attacking Positional Patterns of Play 5', 'Klopp (Liverpool)', 'Switch play then use quick combinations so the defensive midfielder breaks forward to join the attack.', 'Attacking half; 4-3-3 shape starting from LCB, ball supply in centre circle, GK in goal.', 'LCB to LB, inside to LCM who switches to RW high on the flank; RW sets RB, who dribbles inside and passes for the DM''s forward run; DM one-two with CF, then through pass for RW''s third-man run; RW cuts in and scores at the far corner.', NULL, NULL, 'Time the DM''s forward run with the RB''s dribble inside.', '10 + GK', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 50),
  ('Switch for full back''s run into box', 'combination', 'unopposed', 'in_possession', 22, 22, 'Attacking Positional Patterns of Play 6', 'Klopp (Liverpool)', 'Switch play so the far full back makes an advanced run into the box for a cut-back finish.', 'Attacking half; 3 white cones near the edge of the box mark start points of LW, CF and RW; build-up from RCB; GK in goal.', 'RCB to RCM, out to advanced RB, inside to DM stepping up; DM to LW who checks off his cone and sets LCM; LCM slides a timed through pass for the LB; LW, CF and RW move into the box, LB crosses to the far side, RW cuts back for CF to score.', NULL, NULL, 'Front three start off cones and make timed box movements.', '10 + GK', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 60),
  ('Winger inside, through pass to overlap', 'combination', 'unopposed', 'in_possession', 23, 23, 'Attacking Positional Patterns of Play 7', 'Klopp (Liverpool)', 'Winger''s inside movement opens space for a midfielder''s through pass to the overlapping full back.', 'Attacking half of a full pitch, 10 outfield players in Liverpool''s 4-3-3 roles plus a GK in goal; mannequins (or resting centre backs) mark the build-up start near halfway.', 'LCB to DM, forward to CF who drops left and finds LW; LW back to LB; LB firm ground pass across to RCM moving inside; RCM inside for LCM to run onto; LCM diagonal to RW who drops inside and lays back; LCM plays in behind for RB''s overlap; RB cuts the ball into the box where LW, CF and RW arrive; CF scores at back post.', NULL, NULL, 'Winger dropping inside drags the defender and frees the flank for the overlap.', '10 + GK', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 70),
  ('Playing through a high line vs 4', 'phase_of_play', 'opposed', 'in_possession', 24, 24, 'Attacking Positional Patterns of Play 8', 'Klopp (Liverpool)', 'Break a high defensive line with combinations and through passes, then finish with advanced runs.', 'Attacking half; 10 attackers in 4-3-3 vs 4 yellow defenders holding a high line, plus GK; spare teams wait by the sides.', 'Attack starts from LCB and aims to score fast with combinations and passes between the defenders; e.g. LCB-LCM-DM, DM to RCM who carries and threads between yellow LCB and LB for RW''s run; RW squares across the box and LCM finishes at back post. Defenders hold a high line and then track runners once the ball goes in behind.', 'Goal scored = the two teams switch roles.', NULL, 'Timed advanced runs beyond the line; many runners into the box.', '10v4 + GK', 15, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 80),
  ('Playing over a high line vs 4', 'phase_of_play', 'opposed', 'in_possession', 25, 25, 'Attacking Positional Patterns of Play 9', 'Klopp (Liverpool)', 'Beat a high defensive line with a lofted switch over the top and advanced runs to finish.', 'Same as the previous practice: 10 attackers v 4 defenders holding a high line in the attacking half, GK in goal.', 'LCB to DM, DM shifts sideways and goes wide to RW; RW sets RCM who switches with a long aerial ball over the line to LW''s timed run; LW carries into the box and shoots, CF follows in on the rebound while others support.', 'Goal scored = teams switch roles.', 'Variation of practice 8 using a lofted pass over the line.', 'Time the run against the line; follow up rebounds.', '10v4 + GK', 15, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 90),
  ('Possession then GO! fast attack (narrow)', 'combination', 'unopposed', 'in_possession', 26, 26, 'Attacking Positional Patterns of Play 10', 'Klopp (Liverpool)', 'Circulate in positional 4-3-3 roles, then react quickly on the coach''s call to attack and score.', 'Attacking half narrowed by cones/poles; 10 players in 4-3-3 roles start from a centre back, GK in goal.', 'Players pass freely at match speed in their roles for 20-40 passes; on the coach''s GO! they attack and finish fast (e.g. RCM diagonal to LW in the box, LW squares across for RW to score).', 'Ball circulates 20-40 passes before the GO! call.', 'Practice 11 is the full-width progression.', 'Quick reaction to the call; supporting runs into the box.', '10 + GK', 11, 11, 'reduced width', NULL, NULL, NULL, true, true, true, NULL, 100),
  ('Possession then GO! fast attack (full width)', 'combination', 'unopposed', 'in_possession', 27, 27, 'Attacking Positional Patterns of Play 11', 'Klopp (Liverpool)', 'Same positional circulation and quick-reaction attack but using the full width of the pitch.', 'Full width of the attacking half; 10 players in 4-3-3 roles plus GK.', '30-60 passes of positional circulation at match speed; on GO! e.g. DM to dropping CF, across to RW who touches and releases overlapping RB; runners attack the box and RB cuts back for CF to score.', '30-60 passes before the call.', 'Progression of practice 10 (full width).', 'Occupy wide spaces; overlap on the outside.', '10 + GK', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 110),
  ('Quick ball to winger cut-back + counter-press', 'combination', 'unopposed', 'to_defend', 30, 30, 'Positional Patterns + Counter-pressing 1', 'Klopp (Liverpool)', 'Run a set pattern ending in a cut-back finish, then react to the coach''s call with counter-pressing movements.', 'Attacking half; 10 players in 4-3-3 roles, GK in goal, coach with spare balls near the middle.', 'LCB to DM, who carries inside and plays a firm diagonal to advanced LW; LW drives into the box and cuts back for RW to score with CF and RCM arriving. After the attack the coach shouts Counter-press and plays a new ball; all 10 press relative to the new ball''s position.', NULL, NULL, 'Compact pressing shape relative to the ball immediately after the finish.', '10 + GK', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 120),
  ('One-side combos, switch over top + counter-press', 'combination', 'unopposed', 'to_defend', 31, 31, 'Positional Patterns + Counter-pressing 2', 'Klopp (Liverpool)', 'Combine on one side, switch over the top in behind to finish, then counter-press on the call.', 'As practice 1: attacking half, 4-3-3 shape, GK, coach with balls.', 'LCB to DM, diagonal to LW dropping to receive; LW to LCM, wide to LB; LB to LCM who opens up and switches long to RW; RW chips into the box for CF to score. Coach then calls Counter-press and all 10 react to the new ball.', NULL, 'Variation of practice 1 with a different pattern.', 'Coach demands width/movement; follow like a passing drill.', '10 + GK', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 130),
  ('Pattern, counter-press, fast break (2 balls)', 'transition', 'unopposed', 'to_defend', 32, 32, 'Positional Patterns + Counter-pressing 3', 'Klopp (Liverpool)', 'Set pattern into counter-pressing then a fast break with a second ball.', 'Attacking half; 4-3-3 shape, coach with spare balls, GK in goal.', 'RCB-RB-DM, DM to CF who sets LW; LW moves inside to receive and goes wide to RW. At any point the coach calls Counter-press: first ball is abandoned and the 10 press toward a new ball; a player collects it and the team breaks fast to score.', 'Coach can call at any moment; first ball abandoned.', NULL, 'Instant switch from attack to press to fast break.', '10 + GK', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 140),
  ('Through midfield, wide cross + 2nd ball', 'combination', 'unopposed', 'in_possession', 34, 34, '2nd/3rd Ball Attacks 1', 'Klopp (Liverpool)', 'Two quick attacking phases: a pattern through midfield to a wide cross, then a second ball attack.', 'Attacking half; 10 players in 4-3-3 roles, GK, coach with balls at halfway.', 'RCB to DM, to RCM who carries and plays inside to LCM; LCM lays off to RCM; RCM to LW who drives forward and crosses low for RW. Players sprint back to positions and the coach plays the 2nd ball (e.g. LW-LCM-lofted to RW).', 'After the 1st attack, sprint back into shape before the 2nd ball.', NULL, 'Speed of recovery into position between balls.', '10 + GK', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 150),
  ('Through pass for winger cut-back + 2nd ball', 'combination', 'unopposed', 'in_possession', 35, 35, '2nd/3rd Ball Attacks 2', 'Klopp (Liverpool)', 'Left-side through pass for the winger''s cut-back, then a right-side second ball attack.', 'Attacking half; 4-3-3 shape, GK, coach with balls.', 'LCB-LB-LCM, LCM sets onrushing DM who threads into the box for LW; LW squares for RW to score. Players reset; coach passes to RCM who goes wide to overlapping RB; RB to RW who finds CF in the middle to score.', NULL, 'Variation of practice 1.', NULL, '10 + GK', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 160),
  ('Midfield lay-offs, lofted in behind + 2nd ball', 'combination', 'unopposed', 'in_possession', 36, 36, '2nd/3rd Ball Attacks 3', 'Klopp (Liverpool)', 'Possession in midfield with lay-offs, a pass into the forward and a lofted ball in behind to the winger, then a second ball.', 'Attacking half; 4-3-3 shape, GK, coach with balls.', 'LCB-DM-RCB, RCB to RCM who lays off to DM; DM wide to RW back to RB; RB inside to LCM after a big movement; LCM one-two with CF and lofts in behind for LW to shoot, CF on the rebound. Players reset and the coach plays a 2nd ball to attack again.', NULL, 'Variation of previous practices.', 'Big movements to receive; follow up rebounds.', '10 + GK', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 170),
  ('Short combos around the box, inside/outside finish', 'finishing', 'unopposed', 'in_possession', 37, 40, '2nd/3rd Ball Attacks 4', 'Klopp (Liverpool)', 'Fast short combinations around the box and finishing from inside and outside the area across multiple balls.', 'Edge of the box with mannequins as a back four, cones, 2 midfielders (M1, M2) and 2 forwards (F1, F2), a right winger, GK, spare GK and coaches with balls; coach acts as passive defender in part 2.', 'Part 1: F1 then F2 shift the ball off a cone and shoot from outside the box; 3rd ball M2-F1-M1-F2-M1, M1 lofts for F1''s curved run between mannequins, F2 curves the other way to score from F1''s pass. Part 2: M1 aerial pass to RW who beats the passive coach 1v1 and crosses or cuts back for F1/F2/M2. Part 3: spare GK serves a 5th ball to RW, back to M1 who crosses high to the back post; F1 cuts back for M2 to score.', 'Players sprint back into position between balls.', 'Variation 2 of part 1 uses different curved run lanes.', 'Curved runs between defenders; sprint out of the box before the next ball.', '5 + GK (M1, M2, F1, F2, RW)', 5, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 180),
  ('Pass and move, fast attacks 2nd/3rd balls', 'phase_of_play', 'passive', 'in_possession', 41, 42, '2nd/3rd Ball Attacks 5', 'Klopp (Liverpool)', 'Positional pass and move in the centre, then fast attacks with a maximum of 3 passes on new balls.', 'Attacking half; 6 red positional players pass and move in a central zone marked by mannequins and cones, yellow players as defenders, GK, coaches with balls.', 'Reds circulate in their roles; on the coach''s whistle the 1st ball is abandoned and the nearest player takes a 2nd ball for a fast attack (e.g. LW diagonal through ball to RW, cut back for CF). Players reset and the coach serves a 3rd ball for another fast attack (e.g. CF lays off to RCM who lofts over for LCM to score).', 'Score within a maximum of 3 passes.', 'After a set number of reps reds and yellows switch roles.', 'Speed of attack once the whistle goes.', '6 + defenders + GK', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 190),
  ('Pass under pressure, curved run, finish', 'finishing', 'passive', 'in_possession', 45, 45, 'Attacking Combinations and Finishing 1', 'Klopp (Liverpool)', 'Pass out under pressure and finish from a curved run into the box.', 'Just outside the box, left side; queue of players at A with balls, Player B in the centre, coach as passive defender, GK in goal; also run from the right.', 'Coach pressures as A passes to B; B receives in two touches and plays into the box for A''s curved run; A finishes.', 'B uses 2 touches; A finishes in 1-2 touches.', 'A variation follows (practice 2).', 'If you have time, use it - don''t rush the finish.', 'Groups of 3+ + GK', 3, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 200),
  ('Short passing under pressure, move, finish', 'finishing', 'passive', 'in_possession', 46, 46, 'Attacking Combinations and Finishing 2', 'Klopp (Liverpool)', 'Short combination under passive pressure with movement to create a finish.', 'Edge of the box; Players A and B with a passive coach defender, GK, run from both sides.', 'Option 1: A one-two with B, then third pass in behind for B''s run and finish. Option 2: A one-two with B and plays it back to B, who opens up, takes a touch into the box and shoots.', NULL, 'Two options (give and go; pass back, touch and finish).', 'B checks away to create space.', 'Groups of 3+ + GK', 3, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 210),
  ('One-two, lateral third man run, finish', 'finishing', 'unopposed', 'in_possession', 47, 47, 'Attacking Combinations and Finishing 3', 'Klopp (Liverpool)', 'One-two then a through pass for a lateral third-man run and finish.', 'Edge of the box with cones; Players A, B and C (B and C wide), coaches, GK.', 'A to B (or C) who checks off a cone; one-two back to A; A plays into the box for C''s curved third-man run; C finishes in 1-2 touches while B runs parallel to follow up rebounds.', 'Finish in 1 or 2 touches.', 'If the first pass goes to C, B and C swap roles.', 'Timed curved third-man run; follow up on rebounds.', '3 + GK', 3, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 220),
  ('Double one-two, through pass third man run', 'finishing', 'unopposed', 'in_possession', 48, 48, 'Attacking Combinations and Finishing 4', 'Klopp (Liverpool)', 'Two one-twos then a through pass for the lateral third-man run and finish.', 'Edge of the box; Players A, B and C, GK.', 'A one-two with B, then one-two with C, then A slides a pass into the box for B''s third-man run; B finishes in 1-2 touches, C follows up for rebounds.', 'Finish in 1 or 2 touches.', 'Mirror if the first pass goes to C.', 'Parallel follow-up run for rebounds.', '3 + GK', 3, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 230),
  ('One-two, open up, finish + second ball', 'finishing', 'unopposed', 'in_possession', 49, 49, 'Practice 5', 'Klopp (Liverpool)', 'Combine with a one-two, create space to receive and finish, then react to a second ball for a first-time finish.', 'Queue of players at the edge of the box on the left (also run from the right); Player B in the centre; coach with balls; GK in goal.', 'A passes to B and gets it back in a one-two, steps away to make space, receives again, touches into the box and shoots. A then sprints back to a central cone and turns as a coach plays a second ball into the middle, which A meets with a one-touch finish.', 'Second finish is one touch.', 'Run from the right side too.', 'B steps back to create space; A times the run onto the second ball and turns towards goal quickly.', 'Group of attackers + server + GK', NULL, NULL, 'Final third / penalty area', NULL, NULL, NULL, true, true, true, NULL, 240),
  ('Diagonal lofted pass with box runs', 'combination', 'unopposed', 'in_possession', 50, 50, 'Practice 6', 'Klopp (Liverpool)', 'Deliver a well-weighted diagonal lofted ball in behind and attack the box with timed near, centre and far post runs.', 'Wide player on each side (R and L), a left winger, centre forward and right winger in front of the box; coach with balls; GK.', 'R hits a diagonal lofted pass to the far side for L''s run; L squares it across the box while LW, CF and RW attack near post, centre and far post; one of them finishes. Then repeat starting from L on the other side.', NULL, 'Mirror the pattern from the left.', 'Time and weight the lofted ball for the runner; the three runners split to cover all three post areas.', '5 attackers + GK', 6, NULL, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 250),
  ('3-player combination, cross, timed runs', 'combination', 'unopposed', 'in_possession', 51, 51, 'Practice 7', 'Klopp (Liverpool)', 'Lay-off and third-man pass to release a wide runner, then cross for timed runs into the box.', 'Groups of three (A, B, C) on each side outside the box; matching group on the right (A2, B2, C2); coach with balls; GK.', 'A passes to B (back to goal), who lays back to C; C plays a diagonal ball in behind for A''s overlapping run. A crosses while B and B2 from the other side attack the centre of the box to finish. Then the right side group repeats.', NULL, 'Alternate sides.', 'Runners time their arrival to meet the cross.', '6 players in 2 groups of 3 + GK', 7, NULL, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 260),
  ('Switch wide, give-and-go, cross for runs', 'combination', 'unopposed', 'in_possession', 52, 52, 'Practice 8', 'Klopp (Liverpool)', 'Quick one-touch switch to the full-back, a give-and-go with the winger, then a ground or aerial cross for two forwards'' timed runs.', 'Two forwards on cones centrally, left back and left winger wide, highlighted crossing zone and target areas near and far post; mannequin in the box; coach with balls; GK. Mirrored on the right.', 'Coach feeds F1, who passes to F2; F2 plays wide to the LB, who gives to the LW and receives back on the overlap. LB crosses low or high into the centre while F1 and F2 make opposite near/far post runs to finish.', 'All one touch.', 'Repeat on the right with right back and right winger; ground or aerial cross.', 'Forwards wait and do not start the run too early; winger checks before moving to receive.', '4 attackers per side + coach + GK', 5, NULL, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 270),
  ('4-ball long range finishing with support', 'finishing', 'unopposed', 'in_possession', 53, 53, 'Practice 9', 'Klopp (Liverpool)', 'Receive from different angles and shoot from distance with a good directional first touch.', 'Shooter A outside the box with servers (coach/D, B, C, D) around the arc, each with balls; GK; second group works on finishing from just inside the box in the other half and groups swap.', 'A takes four balls in turn: lay-off from the coach to shoot, then moves to receive from B, C and D, each time taking a directional touch and shooting.', 'Shoot with 1 or 2 touches on the first ball.', 'Second group does angled finishing inside the box; groups swap after a set time.', 'Directional first touch into a shooting position.', '5 per group + GK', 6, NULL, 'Edge of the box', NULL, NULL, NULL, true, true, true, NULL, 280),
  ('Quick combinations to set back and finish', 'combination', 'unopposed', 'in_possession', 54, 54, 'Practice 10', 'Klopp (Liverpool)', 'Use short, quick combination play to set the ball back for a runner to finish from different positions.', 'Area between two goals with GKs; three inside players (A-C) and three outside players (1-3) waiting with balls.', 'Outside players combine with inside players in various patterns (lay-offs, one-twos, set-backs) ending with the outside player shooting; each shooter then moves to the opposite end and the next starts with a new ball.', NULL, 'Many different combinations; inside and outside players switch roles after a set time.', 'Use realistic match situations and vary positions.', '6 + 2 GKs', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 290),
  ('Receive from different angles + 1v1 finish', 'finishing', 'opposed', 'in_possession', 55, 55, 'Practice 11', 'Klopp (Liverpool)', 'Move to receive and finish from varied angles, then do the same while shaking off a marker.', 'Central striker A between two goals with GKs; four outside servers (S1-S4) with balls; one defender D.', 'First three balls from S1, S2 and S3 are finished unopposed. Then D becomes active and A must lose his marker to receive from S4, S2 and S3 and score.', 'Can score in either goal in the 1v1 phase.', NULL, 'Trick the defender before moving to receive; servers recover actively for their turn.', '1v1 + 4 servers + 2 GKs', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 300),
  ('End-to-end 3-player combo, long range shot', 'combination', 'unopposed', 'in_possession', 56, 56, 'Practice 12', 'Klopp (Liverpool)', 'Play a quick short one-two and a medium aerial pass, then set for a long range shot.', 'Two goals with GKs; three-player groups on both sides running simultaneously.', 'GK passes to A, who plays a quick one-two with B, then hits a medium aerial pass to C moving off his cone. C passes into the centre to B, who sets for C to shoot from distance.', NULL, 'Players rotate A to B to C to A.', 'Technique on the aerial pass and lay-off.', 'Groups of 3 + 2 GKs', 8, NULL, 'Full pitch length', NULL, NULL, NULL, true, true, true, NULL, 310),
  ('3-player combo, overlap third man, cross', 'combination', 'unopposed', 'in_possession', 57, 57, 'Practice 13', 'Klopp (Liverpool)', 'Third-man overlap down the side ending in a cross and finish.', 'Variation of practice 12: two goals with GKs, three-player groups on both sides at the same time.', 'GK to A, who passes inside to B; B lays off to C, who plays a firm ground pass for A''s run outside. A crosses while B and C run in, one meets it at the back post.', NULL, 'Rotate A to B to C to A.', 'Quick combination, then lift the cross to the second post.', 'Groups of 3 + 2 GKs', 8, NULL, 'Full pitch length', NULL, NULL, NULL, true, true, true, NULL, 320),
  ('Fast break from the centre circle', 'combination', 'unopposed', 'to_attack', 58, 58, 'Practice 14', 'Klopp (Liverpool)', 'Launch a fast break with simple combinations, lay-offs and deep forward runs.', 'Nine players in a team shape inside the centre circle; coach in the middle with balls; GK in goal.', 'Coach plays to any player and all break forward: e.g. LB to LW, lay-back to LCM, forward pass to RW who dribbles and feeds the overlapping RCM, who squares for LW to tap in.', NULL, NULL, 'Explode forward on the coach''s pass with deep runs.', '9 + GK', 10, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 330),
  ('One-two shot then 1v1 vs keeper circuit', 'finishing', 'unopposed', 'in_possession', 59, 59, 'Practice 15', 'Klopp (Liverpool)', 'Shoot from outside the box after a set, then sprint to receive and beat the GK one-on-one.', 'Three stations of 5 players around the edge of the box; goals at both ends with GKs; coach at halfway with balls.', 'C passes to B and gets a set to shoot from outside the box; B then sets for A to shoot. A sprints toward the far goal, receives from the coach and tries to finish 1v1 against the GK.', NULL, 'Rotate stations A to B to C to A.', NULL, '15 in 3 groups of 5 + 2 GKs', NULL, NULL, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 340),
  ('Pairs runs with double switch and crossing zones', 'finishing', 'passive', 'in_possession', 60, 60, 'Practice 16', 'Klopp (Liverpool)', 'Switch play into wide crossing zones and attack crosses in pairs, twice in opposite directions.', 'Two goals with GKs, wide crossing zones on each side, mannequins as defenders; pairs (A and B) start at each end; servers C and D in wide zones; both sides run simultaneously, coaches count goals for both teams.', 'A passes to B, who switches diagonally into C''s wide zone; C crosses and both A and B run in to finish. They then sprint back the other way and D crosses a new ball for them to score in the opposite goal.', 'Teams compete on goals scored.', 'Next pairs repeat after both phases.', NULL, 'Pairs in two teams + wide servers + 2 GKs', NULL, NULL, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 350),
  ('4-player wave, 1-touch overlaps + 2nd ball', 'combination', 'unopposed', 'in_possession', 61, 61, 'Practice 17', 'Klopp (Liverpool)', 'Attack at full speed in waves of four with one-touch overlaps and finish, then counter with a second ball.', 'Two goals with GKs; groups of four (A-D) start across the pitch near one end; coach keeps time and has balls.', 'A passes across to D; D, C and B each use one touch on successive overlaps; A crosses for B, C and D running in to score. The coach then feeds a new ball and all four break fast to score at the other end.', 'Every player must touch the ball before scoring; coach times the wave.', 'Next group of four repeats.', 'Sprint at full pace to get on the overlap.', 'Groups of 4 + 2 GKs', NULL, NULL, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 360),
  ('End-to-end combinations in groups of 3', 'combination', 'unopposed', 'in_possession', 62, 62, 'Practice 18', 'Klopp (Liverpool)', 'Combine up the full length of the pitch with criss-cross, overlap, underlap and direct passes, then finish.', 'Full pitch with goals and GKs at both ends; players in groups of three spread along it.', 'Groups move up the pitch using varied combinations, create a chance in the final area and score; they then get a new ball from the coach and repeat back toward the opposite goal.', NULL, NULL, 'Criss-crossing, overlapping, underlapping, direct passing, combination play, finishes.', 'Groups of 3 + 2 GKs', NULL, NULL, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 370),
  ('Zone possession + fast break on call', 'combination', 'unopposed', 'to_attack', 63, 63, 'Practice 19', 'Klopp (Liverpool)', 'Switch from relaxed ball circulation to an explosive fast break attack on the coach''s call.', 'Four colour groups; three groups each keep a ball in one of three marked zones near halfway; one group attacks; goal with GK.', 'Whites attack and finish, then jog back to the free zone. Coach calls a colour and that group breaks out of its zone with short fast combinations, an overlap and a finish. Continue with the next call.', NULL, NULL, 'Immediate reaction to the call and quick combination play.', '4 groups + GK', NULL, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 380),
  ('3-ball central finishing, cut back + 3v2', 'finishing', 'opposed', 'in_possession', 66, 66, 'Multi-Ball Practice 1', 'Klopp (Liverpool)', 'Finish centrally, then a wide give-and-go and cut back, then a 3v2 with transition.', 'Box with GK; two reds (R1, R2) and two yellows (Y1, Y2), a white winger W, coach in the centre with balls.', 'Ball 1: reds pass diagonally to yellows, who turn, carry into the box and shoot. Ball 2: W passes to a red to start 3v2 against two yellows (e.g. give-and-go and square to score). Ball 3: coach serves a yellow and both yellows plus W attack 3v2 against reds, who switch to defending.', NULL, NULL, 'No waiting between balls; match tempo.', '5 + coach + GK', 6, NULL, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 390),
  ('3-ball through passes to wingers', 'finishing', 'passive', 'in_possession', 67, 67, 'Multi-Ball Practice 2', 'Klopp (Liverpool)', 'Dribble and shoot, then one-twos and through passes past mannequins for wingers'' runs into the box.', 'Mannequins across the edge of the box, cones for dribbling; CF, LCM, RCM, LW and RW; coach with balls; GK.', 'Ball 1: CF dribbles through cones and shoots from the edge of the box. Ball 2: RCM passes to CF, gets it back and plays through the mannequins for LW''s run to score. Ball 3: LCM plays wide to RW, who lays off for RCM; RCM threads a pass for RW''s run and RW squares for LW or CF to finish.', NULL, 'Ball 2 can be a ground or lofted pass to the LW.', 'Well-timed runs onto the through ball.', '5 + GK', 6, NULL, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 400),
  ('4-ball crossing, receive and shoot', 'finishing', 'passive', 'in_possession', 68, 69, 'Multi-Ball Practice 3', 'Klopp (Liverpool)', 'Attack crosses from both full-backs with one-touch finishes and finish from coach passes in between.', 'Forward, winger and midfielder in the box with mannequins; right back and left back wide with balls; coach centrally with balls; GK.', 'Ball 1: F, W and M make runs and RB touches forward and crosses, one-touch finish. Ball 2: coach passes to M for a one-touch finish. Ball 3: same from the LB''s side. Ball 4: coach plays to F, who drops, opens up on the half-turn, moves inside and shoots.', 'One-touch finishing on crosses.', 'Full-backs vary crosses including pull-backs to M.', NULL, '5 + coach + GK', 6, NULL, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 410),
  ('4-ball finishes, quick passes, switch for cross', 'finishing', 'unopposed', 'in_possession', 70, 71, 'Multi-Ball Practice 4', 'Klopp (Liverpool)', 'Different finishes plus a two-touch passing phase and switch to the full-back for a cross.', 'CF, LW, RW, midfielder M and both full-backs around the box; coaches with balls; GK. Shown on the left, also done on the right.', 'Ball 1: CF touches and shoots. Ball 2 and 3: LW plays a slow pass to RW, RW lofts into the box for LW to score, then RW plays give-and-go with CF and crosses low for LW or CF. Ball 4: M exchanges passes with CF, LW and RW, then switches to the LB, who runs forward and either crosses deep or dribbles and crosses low while the three forwards attack the box.', 'Two touches in the pass-and-back phase.', 'Also run with the right back.', NULL, '6 + GK', 7, NULL, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 420),
  ('Positional 1-touch combinations around box', 'combination', 'passive', 'in_possession', 72, 73, 'Multi-Ball Practice 5', 'Klopp (Liverpool)', 'Positional one-touch interplay in and around the box ending in shots, lofted passes, switches and cut backs.', 'Full team shape (DM, LCM, RCM, CF, LW, RW, LB, RB) around mannequins outside the box; coaches with balls; spare player; GK.', 'Ball 1: DM and CF exchange passes, CF turns and shoots while mids, wingers and full-backs move the ball round the mannequins. Ball 2: LCM lofts for RW to score. Ball 3: RCM switches across to LCM and various combinations release the LB on the overlap to cut back. Ball 4: DM passes to a winger, who sets for LCM to play through for the LB, who crosses for LW, CF, RW or RB.', 'One touch where possible.', 'Option where LW lays off to CF who feeds LB; mirror on the right with the RB delivering.', NULL, '8-9 + GK', 9, NULL, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 430),
  ('CF and wingers combine, 5-ball drill', 'finishing', 'passive', 'in_possession', 74, 75, 'Multi-Ball Practice 6', 'Klopp (Liverpool)', 'Centre forward and wingers combine in and around the box with five different finishes.', 'CF, LW, RW, LB and players queueing; coaches with balls, one on the by-line; GK.', 'Ball 1: CF receives, turns and shoots while wingers play one-twos. Ball 2: RW lofts for LW. Ball 3: LW slow pass to RW, give-and-go with CF and low cross for CF or LW. Ball 4: coach on the by-line feeds RW for a first-time finish. Ball 5: LB passes to CF, who dummies to LW; LW one-two with CF then feeds the LB''s run, who crosses for LW, RW or CF.', 'First-time finish on ball 4.', NULL, NULL, '5+ + GK', 6, NULL, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 440),
  ('3 forwards continuous finishing, 7 balls', 'finishing', 'passive', 'in_possession', 76, 77, 'Multi-Ball Practice 7', 'Klopp (Liverpool)', 'Front three finish continuously from different types of assist.', 'CF, LW, RW around mannequins at the edge of the box; coaches with balls including one on the by-line; GK.', 'Balls 1-4 as the previous drill (touch and shoot, lofted pass to LW round a mannequin, give-and-go and low cross, coach feed for first-time finish). Balls 5-7: LW receives, turns in and shoots; CF drops at an angle then checks forward to meet a pass into the box; RW drops then checks forward to meet a lofted pass.', NULL, NULL, 'Drop at an angle, then make the opposite forward movement to meet the ball.', '3 + servers + GK', 5, NULL, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 450),
  ('Technical 8-ball central finishing variations', 'finishing', 'unopposed', 'in_possession', 78, 79, 'Multi-Ball Practice 8', 'Klopp (Liverpool)', 'Technical finishing variations with both feet from central positions, ending in a 1v1 with the keeper.', 'Forwards F1 and F2 centrally, LW and RW, four queues of midfielders (M1-M4) further out, cones to dribble through; coach with balls; GK.', 'Ball 1: F1 fakes, touches and shoots. Ball 2: F2 dribbles through four cones and shoots. Ball 3: LW give-and-go with F1 and right-foot shot. Ball 4: RW give-and-go with F2 and low cross or cut back. Balls 5-7: coach serves along the ground or in the air for LW, F2 and F1 to turn or meet and finish. Ball 8: a central midfielder dribbles into the box and goes 1v1 with the GK.', 'Specific foot per finish (left/right as set).', 'Midfielders rotate in to become the new LW, RW, F1 and F2.', NULL, '4 front players + 4 queues of midfielders + GK', NULL, NULL, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 460),
  ('Positional combos around the box, 8 balls', 'combination', 'passive', 'in_possession', 80, 82, 'Multi-Ball Practice 9', 'Klopp (Liverpool)', 'Positional attacking combinations around the box with eight different finishes, including a long switch and a 1v1 with the keeper.', 'CF, LW, RW, LCM, RCM, LB, RB, LCB around mannequins; servers S1-S3 and coaches with balls; GK.', 'Balls 1-4: CF one-two with LCM, turn and shoot; RW lofts for LW; slow pass then RW give-and-go and low cross; coach feed for RW''s first-time finish. Ball 5: LB to CF to LW, back to LCM who plays through for the overlapping LB to beat a mannequin and cut back. Ball 6: coach chips from the by-line for LCM to volley. Ball 7: LCB switches long to RB, who dribbles in and feeds the overlapping RCM to cross low. Ball 8: RB receives from S3, dribbles into the box and goes 1v1 with the GK.', NULL, NULL, NULL, '8-9 + servers + GK', 10, NULL, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 470),
  ('4-ball one-twos, shots, give-and-go crosses', 'finishing', 'passive', 'in_possession', 83, 84, 'Multi-Ball Practice 10', 'Klopp (Liverpool)', 'Two teams finish at opposite goals after one-twos, turns, dribbles, lofted passes and crosses.', 'Area between two goals with GKs, mannequins in the middle, cones; reds (R1-R4) attack one goal and yellows (Y1-Y4) the other, with queues behind each goal.', 'Reds: pass-and-turn shots, dribble through cones and shot, wide angle finish, set-back shot, then a give-and-go and cross or cut back. Yellows: turn and shoot, slow pass then lofted pass for a run, give-and-go and low cross, then a one-two and deep cross. Players run back into position after the first three balls.', NULL, 'Cross variations: give-and-go then cross, or deep cross.', NULL, 'Two teams of 4 + queues + 2 GKs', 10, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 480),
  ('5-ball wing play, dribbling and 1v1s', 'finishing', 'opposed', 'in_possession', 85, 87, 'Multi-Ball Practice 11', 'Klopp (Liverpool)', 'Wing play, dribbling through poles and crossing, ending in a race to finish 1v1 against the keeper.', 'Two goals with GKs, mannequins and poles; reds and yellows (5 each) attacking opposite goals with extra players on the by-lines; coaches count goals.', 'Each team runs: pass-and-turn shots, one-two then dribble through poles to shoot, slow pass then lofted pass for a run, give-and-go and cross for teammates, wide give-and-go and cross, then a wide-angle shot. On the fifth ball one red and one yellow dribble from opposite by-lines and each finishes 1v1 against the GK.', 'Coach keeps a total goal count for both teams.', 'Players change roles and teams change ends after a set time.', NULL, 'Two teams of 5 + 2 GKs', 12, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 490),
  ('4-ball finishing + 5-second fast break', 'finishing', 'unopposed', 'to_attack', 88, 89, 'Multi-Ball Practice 12', 'Klopp (Liverpool)', 'Finishing combinations followed by a four-player fast break that must score within five seconds.', 'Two goals with GKs; two groups of three at each end running the same sequence, extra players on the halfway line and by-lines.', 'Balls 1-3: Player 2 shoots; slow pass then Player 3 lofts for Player 1''s run; Player 3 give-and-go with Player 2 and low cross. Ball 4: an outside player serves a new ball and a fourth player joins from halfway; the reds break to the opposite goal, then the yellows break the other way.', 'Fast break must score within 5 seconds.', NULL, NULL, '2 groups of 3 + extra players + 2 GKs', 10, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 500),
  ('Feint and shoot, lofted pass, give-and-go + 3v2', 'finishing', 'opposed', 'in_possession', 90, 91, 'Multi-Ball Practice 13', 'Klopp (Liverpool)', 'Three finishing patterns for the front three, then a 3v2 attack against defenders who can counter.', 'CF, LW and RW around the edge of the box; two defenders (D) waiting on the by-line; coach with balls; marked line further out; GK.', 'Ball 1: CF feints and shoots. Ball 2-3: RW slow pass, LW lofts for RW to score, then LW give-and-go with CF and low cross for RW or CF. Ball 4: reds drop back, coach serves and LW, RW and CF attack 3v2 against two defenders who step in from the by-line.', 'If the defenders win the ball they score by dribbling over the marked line.', NULL, 'Well-timed run between the two defenders to receive the through ball.', '3v2 + coach + GK', 6, NULL, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 510),
  ('Turn and shoot, lofted pass, give-and-go + 3v2', 'finishing', 'opposed', 'in_possession', 92, 93, 'Multi-Ball Practice 14', 'Klopp (Liverpool)', 'Pairs finish after one-twos, a lofted pass and a give-and-go cross, then a 3v2 attack with a counter line for the defenders.', 'Three pairs (whites, yellows, blues) around the edge of the box plus a red R; one blue sits out; coach with balls; marked line; GK.', 'Ball 1: W1 and Y1 one-two, W1 turns and shoots. Ball 2-3: same one-two then W2 lofts for R; after a slow pass W2 gives and goes with W1 and crosses low. Ball 4: two yellows and a red attack 3v2 against the two whites.', 'Whites defend the goal; if they win it they dribble past the marked line.', NULL, NULL, '3v2 + extras + GK', 7, NULL, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 520),
  ('5-ball give-and-go finishing + 6v4 attack', 'finishing', 'opposed', 'in_possession', 94, 95, 'Multi-Ball Practice 15', 'Klopp (Liverpool)', 'Pass, receive, shoot and give-and-go finishing, then a transition to a 6v4 attack.', 'Attackers A1-A6 around the box, four yellow defenders waiting on the by-line, coach with balls, marked line; GK.', 'Balls 1-4: A1 and A2 interchange and A1 turns to shoot; A2 shoots from a wide angle; A3 sets for A4 after a one-two; A4 give-and-go with A2 and low cross for A1 or A3. Ball 5: A5 and A6 enter, coach serves A5 and six attackers play against four defenders who run in from the by-line.', 'Defenders who win the ball score by dribbling past the marked line.', 'Coach sometimes serves the 5th ball to the defenders, and sometimes adds a 6th ball to keep the 6v4 going.', 'Use combinations to get in behind.', '6v4 + GK', 11, NULL, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 530),
  ('4-ball finishing + quick 7v4 attack', 'finishing', 'opposed', 'in_possession', 96, 97, 'Multi-Ball Practice 16', 'Klopp (Liverpool)', 'Three finishing patterns, then a quick transition into a 7v4 attack against a back four.', 'Reds R1-R3 at the edge of the box, extra reds R4-R7 waiting wide and deeper, four yellow defenders on the by-line, coaches with balls; GK.', 'Ball 1: R2 shoots from the edge. Balls 2-3: slow pass, R3 lofts for R1''s run, then R3 give-and-go with R2 and low cross for R1 or R2. Ball 4: coach feeds R3, three new reds join and four yellows run in to defend as a back four in a 7v4, reds combining to get in behind and score.', NULL, NULL, 'Spin in behind your direct opponent; diagonal pass for the runner to cross low.', '7v4 + GK', 12, NULL, 'Final third', NULL, NULL, NULL, true, true, true, NULL, 540),
  ('Throw-in receive and escape 3v2 channels', 'phase_of_play', 'overload', 'set_piece', 100, 100, 'Small to Large Sided Games 1', 'Klopp (Liverpool)', 'Receiving a throw-in under pressure and playing out of the tight touchline area to score.', 'Narrow channels marked along the touchline, a mini goal at the far end of each; groups of 5 (3 attackers incl. thrower v 2 defenders).', 'Each rep starts with an attacker throwing in; the three attackers work the ball through the two defenders and finish in the mini goal. If defenders win it they counter to score.', 'Every restart (goal or ball out) is a fresh throw-in for the attackers.', 'Practice 2 scales it to 5v4.', NULL, '3v2 per channel, groups of 5', 5, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 550),
  ('Throw-in receive and escape 5v4 channels', 'phase_of_play', 'overload', 'set_piece', 101, 101, 'Small to Large Sided Games 2', 'Klopp (Liverpool)', 'Bigger-group version of breaking out from a throw-in under pressure.', 'Wider channels along the touchline with a mini goal at the end; groups of 9 (5 attackers incl. thrower v 4 defenders).', 'Attackers start with a throw-in, combine past the four defenders and score in the mini goal; defenders try to win it and score themselves.', 'Always restart with a new throw-in to the attacking side.', NULL, NULL, '5v4 per channel, groups of 9', 9, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 560),
  ('High tempo 4v4 shoot-on-sight game', 'small_sided_game', 'opposed', 'in_possession', 102, 102, 'Small to Large Sided Games 3', 'Klopp (Liverpool)', 'Playing at high tempo and shooting the moment space opens.', 'Small area with two full goals and GKs; 4v4 plus keepers, coaches on the side with spare balls.', 'Short intense bursts: GK rolls the ball out short, medium or long and the team attacks, shooting early whenever an opening appears. A team that wins the ball tries to shoot quickly too.', '40-second bursts with rests; after a goal the scoring team restarts from its own GK; ball out = other GK restarts; coaches keep the score.', NULL, 'Under pressure, get out and finish; shoot early.', '4v4 + 2 GKs', 10, 10, NULL, NULL, NULL, NULL, true, true, true, NULL, 570),
  ('Winner stays on 3v3 shooting game', 'small_sided_game', 'opposed', 'in_possession', 103, 103, 'Small to Large Sided Games 4', 'Klopp (Liverpool)', 'Taking every shooting chance, including from distance.', 'Small pitch with two goals and GKs; two teams of 3 playing, a third team waiting outside.', '3v3 starting from the GK; the team on the ball shoots whenever there is room, even from deep. Defenders win it and attack quickly.', 'Scoring team restarts from its GK and stays on; the team that concedes swaps with the waiting team; ball out = opposite GK restarts.', NULL, 'Close down the ball - no shot allowed.', '3v3 + 2 GKs + waiting team of 3', 11, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 580),
  ('Direct play shoot-early 4v4 game', 'small_sided_game', 'opposed', 'in_possession', 104, 104, 'Small to Large Sided Games 5', 'Klopp (Liverpool)', 'Going direct and shooting early, including from your own half.', 'Small pitch with halfway line, two goals with GKs; 4v4.', 'From the GK the attacking team plays direct and looks to shoot early, lots of shots from inside its own half. The pressing team blocks shots and counters fast when it wins the ball.', 'Scorers restart from own GK; ball out = opposite GK; pressing team did not commit numbers into the opponent half.', NULL, 'Direct ball, at least one good chance; use the chaos; praise good goals.', '4v4 + 2 GKs', 10, 10, NULL, NULL, NULL, NULL, true, true, true, NULL, 590),
  ('4v4 with four end support players', 'small_sided_game', 'overload', 'in_possession', 105, 105, 'Small to Large Sided Games 6', 'Klopp (Liverpool)', 'Using outside supports and the overload to create lots of chances.', 'Small pitch, two goals with GKs; 4v4 inside plus 4 neutral end players, one on each side of each goal.', 'Team on the ball uses the end players to bounce passes and get support, then attacks the goal. Defenders block lanes and, on winning it, counter using the outside players too.', 'End players one-touch; scorers restart from own GK; ball out = opposite GK.', NULL, 'Bounce off the end players and support quickly.', '4v4 (+4) + 2 GKs', 14, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 600),
  ('5v5 with wide side zones', 'small_sided_game', 'opposed', 'in_possession', 106, 106, 'Small to Large Sided Games 7', 'Klopp (Liverpool)', 'Using the full width of the pitch to open up the opponent.', 'Pitch with two goals and GKs plus a channel marked down each side; 5v5.', 'From the GK, teams stretch play into the side zones and form triangles to create openings and score; defenders win it and attack under the same rules.', 'Side zones: receive passes only (no dribbling in), no shooting from inside them, only one defender may enter to press or block.', NULL, 'Triangles; we need width.', '5v5 + 2 GKs', 12, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 610),
  ('Play in behind then break low block', 'small_sided_game', 'overload', 'in_possession', 107, 108, 'Small to Large Sided Games 8', 'Klopp (Liverpool)', 'Exploiting space behind a high line, then breaking down a deep low block.', 'Pitch with marked halfway line, two goals and GKs; 5v5 plus a Joker with the attacking team.', 'Stage 1: defenders must all stay in the attackers'' half (until the ball passes them) so attackers use the Joker overload to play balls in behind. Stage 2: defenders sit in their own half and only one may press there, so attackers must break a low block. Stage 3: free game.', 'Stage 1 one-touch; stage 2 two-touch; scorers restart from GK; defenders counter on winning it.', 'Three changing conditions within the session ending in a normal 5v5 (+1).', 'Offer runs in behind, keep offering.', '5v5 (+1) + 2 GKs', 13, 13, NULL, NULL, NULL, NULL, true, true, true, NULL, 620),
  ('Three-team 3-goal 5v5v5 game', 'small_sided_game', 'opposed', 'in_possession', 109, 109, 'Small to Large Sided Games 9', 'Klopp (Liverpool)', 'Playing out and scoring quickly against two opponents.', 'Area with three goals and GKs, one per team; three teams of 5.', 'The team on the ball, starting from its GK, can score in either of the other two goals; both other teams try to win it and then score in one of their two opposing goals.', 'Scorers restart from own GK; teams switch goals after a set time.', NULL, NULL, '5v5v5 + 3 GKs', 18, 18, NULL, NULL, NULL, NULL, true, true, true, NULL, 630),
  ('5v5 plus Joker build through pressure', 'small_sided_game', 'overload', 'in_possession', 110, 110, 'Small to Large Sided Games 10', 'Klopp (Liverpool)', 'Building up through pressure with the Joker, and pressing collectively when defending.', 'Pitch with two goals and GKs; 5v5 plus a Joker for the team on the ball.', 'From the GK the team in possession uses combinations and the Joker overload to break pressure and score; defenders press, close lanes and counter quickly when they win it.', 'Scorers restart from own GK; ball out = opposite GK.', NULL, 'Put pressure on; show for the ball.', '5v5 (+1) + 2 GKs', 13, 13, NULL, NULL, NULL, NULL, true, true, true, NULL, 640),
  ('5v5 five passes before shooting', 'small_sided_game', 'opposed', 'in_possession', 111, 111, 'Small to Large Sided Games 11', 'Klopp (Liverpool)', 'Keeping the ball under pressure before attacking the goal.', 'Small pitch with two goals and GKs; 5v5.', 'Normal 5v5 from the GK, but a team must string 5 passes together before it may shoot; the coach counts aloud. A team that wins the ball also needs 5 passes.', '5 passes before shooting; scorers restart from own GK; ball out = opposite GK.', NULL, NULL, '5v5 + 2 GKs', 12, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 650),
  ('Corners plus counter-attack 8v8', 'set_piece', 'opposed', 'set_piece', 112, 112, 'Small to Large Sided Games 12', 'Klopp (Liverpool)', 'Attacking and defending corners, then countering after a clearance.', 'Large area towards one main goal with a second goal at the far end; 8v8 plus GKs.', 'Each rep starts with a corner; taker''s arm signal picks the option (one arm short, two near post, none deep). Attackers score or win the second ball; defenders clear, win it and counter fast to the opposite goal; play continues as a game.', 'Ball out = new corner; corners taken from both sides.', NULL, NULL, '8v8 + 2 GKs', 18, 18, NULL, NULL, NULL, NULL, true, true, true, NULL, 660),
  ('Wide free kicks plus counter 8v8', 'set_piece', 'opposed', 'set_piece', 113, 113, 'Small to Large Sided Games 13', 'Klopp (Liverpool)', 'Attacking and defending wide free kicks, then countering.', 'Large area towards one goal with a counter goal at the far end; 8v8 plus GKs, a 2-man wall.', 'Starts with a crossed free kick from wide; attackers try to score or win the second ball; defenders clear and counter fast to the opposite goal; play continues as a normal game.', 'Ball out = new free kick; taken from both sides.', NULL, NULL, '8v8 + 2 GKs', 18, 18, NULL, NULL, NULL, NULL, true, true, true, NULL, 670),
  ('10v10 four-goal six-pass game', 'conditioned_game', 'opposed', 'in_possession', 114, 114, 'Small to Large Sided Games 14', 'Klopp (Liverpool)', 'Possession play then switching to attack any of four goals.', 'Half pitch with four goals and 4 GKs (one each end and one each side); 10v10.', 'A team must complete 6 passes (coach counts) before it may score in any of the 4 goals; after a goal any player can take a new ball from any GK and needs 6 passes again.', '2-touch; 6 passes before scoring; a GK may help the team in possession but that team then cannot score in that GK''s goal.', NULL, NULL, '10v10 + 4 GKs', 24, 24, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 680),
  ('2v1 overlap attack into 3v2 transition', 'transition', 'overload', 'to_defend', 117, 117, 'Transition Games 1', 'Klopp (Liverpool)', 'Supporting runs to finish a 2v1 fast, then switching to defend against a 3v2.', 'Area in front of a goal with GK; red pairs start beside the far end, white players at the goal line and sideline, coaches with balls.', 'Red passes to a teammate and overlaps while a white runs on to defend: 2v1 to score. Immediately two more whites bring a new ball in and three whites attack the two reds back the other way, who must sprint back and defend.', NULL, NULL, 'Exploit the overload, run past quickly, recover hard.', '2v1 then 3v2 + GK', 6, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 690),
  ('Receive and finish, 3v2 then 4v6', 'transition', 'overload', 'to_defend', 118, 119, 'Transition Games 2', 'Klopp (Liverpool)', 'Finishing then reacting instantly to defend outnumbered transitions.', 'Large area with one goal and GK at each end; red attackers, yellow waiting at the far goal line, coaches feeding balls.', 'Ball 1 and 2: coach feeds reds who receive and finish unopposed. Ball 3: a yellow dribbles in with two more to attack 3v2 against reds who must recover. Ball 4: reds bring a ball and four attack while six yellows defend and counter.', 'Coaches keep feeding balls until a goal, then restart.', NULL, 'Quick switch from attack to defence.', 'multi-ball: unopposed, 3v2, 4v6 + 2 GKs', 12, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 700),
  ('Finishing angles then 3v3 transition', 'transition', 'opposed', 'to_defend', 120, 121, 'Transition Games 3', 'Klopp (Liverpool)', 'Finishing after receiving from different angles, then counter-pressing in a 3v3.', 'Area with goal and GK; 6 red attackers, 6 white servers by the goal line, 6 yellow defenders.', 'Ball 1 red turns and shoots; ball 2 wider pass, set back for a shot; ball 3 give-and-go then cut-back finish. Ball 4: a new ball to the reds while three yellows sprint in to press 3v3; if yellows win it they counter.', NULL, NULL, 'Shoot in front of goal; press hard on transition.', '6 reds, 6 whites, 6 yellows + GKs', 18, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 710),
  ('5-ball give-and-go finishing into 4v4+4', 'transition', 'overload', 'to_defend', 122, 123, 'Transition Games 4', 'Klopp (Liverpool)', 'Combination finishing then immediate transition to defend.', 'Area with a goal at each end; 4 reds near the top box, 4 yellows on the end line, 4 whites outside, coaches with balls.', 'Balls 1-4: shot from edge of box, lofted pass for a run, slow pass then give-and-go, drop and cut-back finish. Ball 5: the four yellows attack 4v4 and reds must defend; when reds win it, they pass to a white and the four whites join for a 4+4 v 4 counter.', NULL, NULL, 'Give and go quickly; don''t let them out.', '4v4 (+4) + GKs', 14, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 720),
  ('3-ball finishing into 4v4 and 5v4', 'transition', 'opposed', 'to_defend', 124, 125, 'Transition Games 5', 'Klopp (Liverpool)', 'Finishing combinations then defending and countering in quick transitions.', 'Area with goals at each end and GKs; reds near the box, yellows on the end line, an extra red with the coach.', 'Balls 1-3: shot from edge, lofted pass for a run, slow pass then give-and-go finish. Ball 4: four yellows attack 4v4 and reds defend. Ball 5: a new red dribbles in from the far end for a 5v4 counter.', NULL, NULL, NULL, '4v4, then 5v4 + GKs', 10, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 730),
  ('Wide zone crossing into 5v4/5v8', 'transition', 'overload', 'to_defend', 126, 127, 'Transition Games 6', 'Klopp (Liverpool)', 'Crossing and box runs, then defending and attacking in transitions.', 'Area with goals at both ends and side zones near the top goal; 4 central reds, wide reds, yellows on the end line, more reds on the far end.', 'Balls 1-2: ball goes out wide to a red in the side zone who crosses for the three box runners (near post, far post, cut-back). Ball 3: four yellows attack 5v4 and reds must defend. Ball 4: a red at the far end brings a new ball, three more reds join for a 5v8 type attack.', 'If reds win it in ball 3 they continue attacking with the extra players.', NULL, NULL, '5v4 then 8v5 + GKs', 14, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 740),
  ('Front three finishing into 9v7 transition', 'transition', 'overload', 'to_defend', 128, 129, 'Transition Games 7', 'Klopp (Liverpool)', 'Return passing and finishing by wingers/CF, then defending a counter.', 'Large area with two goals and GKs; front three plus midfielder near the top box, a 9-player red team and 6 yellows.', 'Ball 1 return passes with the CF who turns and shoots; ball 2 to the left winger who combines with the CF and shoots; ball 3 to right winger, give-and-go, cross. Ball 4: the coach serves a new ball to the reds, nine reds attack while the yellows sprint back to defend; yellows win it and counter.', NULL, NULL, NULL, '9v7 + GKs', 18, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 750),
  ('Three-team 5v5v5 two-zone counter game', 'transition', 'opposed', 'to_attack', 130, 130, 'Transition Games 8', 'Klopp (Liverpool)', 'Pressing to win the ball and countering quickly over halfway.', 'Area split into two equal halves with a goal and GK at each end; three teams of 5, middle team defends in both halves.', 'One team attacks 5v5 in one half; defenders press and on winning it break across halfway to attack the third team. The team that cannot leave its half waits.', 'Scorers get a new ball from the coach and attack the opposite goal; otherwise restart from GK; 2-touch at first, then unlimited.', 'Touch limit lifted after a period.', NULL, '5v5v5 + 2 GKs', 17, 17, NULL, NULL, NULL, NULL, true, true, true, NULL, 760),
  ('Three-team 6v6v6 40-second counter game', 'transition', 'opposed', 'to_attack', 131, 131, 'Transition Games 9', 'Klopp (Liverpool)', 'Winning the ball and countering to score within a time limit.', 'Area split into four zones with a goal and GK at each end; three teams of 6.', 'Reds attack 6v6 in one half; whites press and on winning it get over halfway to attack the yellows. Yellows cannot drop into the final zone to defend.', 'Counter must score within 40 seconds; no offside; scorers get a new ball from the coach and attack the opposite goal, else restart from GK.', 'Practice 10 adds offside.', 'Movement.', '6v6v6 + 2 GKs', 20, 20, NULL, NULL, NULL, NULL, true, true, true, NULL, 770),
  ('Three-team 6v6v6 counter game with offside', 'transition', 'opposed', 'to_attack', 132, 132, 'Transition Games 10', 'Klopp (Liverpool)', 'Countering while timing runs against an offside line.', 'Area in four zones with a goal and GK at each end; three teams of 6.', 'As practice 9: reds attack in one half, whites press and counter over halfway against the yellows, who cannot retreat into the final zone.', 'Offside applies; reds cannot leave the half; scorers get a new ball and attack the opposite goal, else restart from GK.', NULL, NULL, '6v6v6 + 2 GKs', 20, 20, NULL, NULL, NULL, NULL, true, true, true, NULL, 780),
  ('Three-team 6v6v6 with wide Jokers', 'transition', 'overload', 'to_attack', 133, 133, 'Transition Games 11', 'Klopp (Liverpool)', 'Using wide Jokers to attack and counter quickly.', 'Area split into zones including side channels for wide Jokers, plus 1 central Joker who can play in either half; three teams of 6, goals and GKs at each end.', 'Reds attack 7v6 with the central Joker; whites press, win it and cross halfway to counter the yellows using the wide Jokers.', 'All players 2-touch; scorers get a new ball from the coach and attack the opposite goal, else restart from GK.', NULL, NULL, '6v6v6 (+3) + 2 GKs', 23, 23, NULL, NULL, NULL, NULL, true, true, true, NULL, 790),
  ('8v8+1 five-second counter-attack game', 'transition', 'overload', 'to_attack', 134, 136, 'Transition Games 12', 'Klopp (Liverpool)', 'Building up then finishing, or countering, within 5 seconds of crossing halfway.', 'Large area with two goals and GKs plus side Jokers; 8v8 plus a Joker, coach counting.', 'Part 1: whites with Joker build up from the GK to get into the attacking half, then must score within 5 seconds (counted down). Part 2: if reds win the ball they attack to score. Part 3: reds start with the ball; whites win it and must counter and score within 5 seconds.', '5 seconds to finish after crossing halfway; ball out by whites = new ball to reds, ball out by reds = new ball to whites for an unopposed 5-second counter.', 'Three parts: build-up, win and score, win and counter.', 'Speed of finish.', '8v8 (+3) + 2 GKs', 21, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 800)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'j-rgen-klopp-80-attacking-combinations-finishing-positional-patterns-of-play-tra') b;
